//! Z4's frame as generated bytes (driver/docs/nanopc-t6-mali.md, "Submit
//! (Z4)"): the board crate (driver/rust, yakogl-drivers) cannot run YakoGL's
//! frame builder, so driver/rust/src/board/nanopc_t6_frame.rs holds what
//! L1's builder ([`l1::build_triangle_frame`] over src/mali/frame.rs) puts
//! in its five arenas and its command stream, at the VAs Z4 maps them at.
//! This test builds that frame again and compares the file's text with what
//! it would generate, byte for byte. With YK_T6_FRAME_BLESS=1 it writes the
//! file instead:
//!
//!   YK_T6_FRAME_BLESS=1 cargo test -p yakogl-mali-panthor --test t6_frame_blob
//!
//! The VAs are in the group's VM (sched.rs's `GROUP_AS` 1, where the stream
//! runs and the tiler reads), and clear of Z3's firmware VAs in AS0 too
//! (0x0 to 0x0410_0000, board::nanopc_t6_fw) so that a mapping in either
//! space cannot overlap them: the arenas, the geometry buffer and the target
//! at 0x1_0200_0000 and up, above sched.rs's test ring (0x1_0080_0000) and
//! sync object (0x1_0090_0000); the heap's first chunk at 0x8000_00a0_0000,
//! a 2 MiB chunk above heap.rs's pool at 0x8000_0001_5000 in the kernel VA
//! range, the address L1's own pin builds with.

use std::fmt::Write;

use yakogl::mali::arena::Arena;
use yakogl::mali::cs::Stream;
use yakogl_mali_panthor::l1::{self, build_context, FrameArenas};

/// The Z4 VAs and sizes the frame is built for.
const CTX_VA: u64 = 0x1_0200_0000;
const DESC_VA: u64 = 0x1_0201_0000;
const CODE_VA: u64 = 0x1_0202_0000;
const SPDS_VA: u64 = 0x1_0203_0000;
const DATA_VA: u64 = 0x1_0204_0000;
/// The arenas' memory (L1's pin's sizes).
const CTX_SIZE: usize = 0x1000;
const DESC_SIZE: usize = 0x4000;
const CODE_SIZE: usize = 0x1000;
const SPDS_SIZE: usize = 0x1000;
const DATA_SIZE: usize = 0x1000;
const GEOMETRY_BUFFER_VA: u64 = 0x1_0210_0000;
const TARGET_VA: u64 = 0x1_0300_0000;
const HEAP_FIRST_CHUNK_VA: u64 = 0x8000_00a0_0000;
const HEAP_CHUNK_SIZE: u32 = 2 << 20;
/// `user_regs(96, 4)` (L1's pin) and the G610's `TILER_FEATURES` max_levels.
const USER_REGS: u32 = 92;
const TILER_MAX_LEVELS: u32 = 8;
const DRAW: bool = true;

const PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../driver/rust/src/board/nanopc_t6_frame.rs");

/// The built frame: each arena's used bytes, the stream's words and the FBD
/// pointer.
struct Built {
    arenas: [(&'static str, u64, usize, Vec<u8>); 5],
    words: Vec<u64>,
    fbd_pointer: u64,
}

fn build() -> Built {
    let mut mem = [vec![0u8; CTX_SIZE], vec![0; DESC_SIZE], vec![0; CODE_SIZE], vec![0; SPDS_SIZE], vec![0; DATA_SIZE]];
    let mut words = vec![0u64; 256];
    let [m_ctx, m_desc, m_code, m_spds, m_data] = &mut mem;
    let mut ctx = Arena::new("context", CTX_VA, m_ctx).expect("arena");
    let mut desc = Arena::new("desc", DESC_VA, m_desc).expect("arena");
    let mut code = Arena::new("code", CODE_VA, m_code).expect("arena");
    let mut spds = Arena::new("spds", SPDS_VA, m_spds).expect("arena");
    let mut data = Arena::new("data", DATA_VA, m_data).expect("arena");
    let c = build_context(&mut ctx, HEAP_FIRST_CHUNK_VA, HEAP_CHUNK_SIZE, GEOMETRY_BUFFER_VA, TILER_MAX_LEVELS)
        .expect("context");
    let mut cs = Stream::new(&mut words, USER_REGS);
    let a = FrameArenas { desc: &mut desc, code: &mut code, spds: &mut spds, data: &mut data };
    let f = l1::build_triangle_frame(a, &mut cs, &c, TARGET_VA, DRAW).expect("the frame builds");
    let words = cs.words().to_vec();
    let arena = |a: &Arena, name| (name, a.base(), a.capacity(), a.used().to_vec());
    Built {
        arenas: [
            arena(&ctx, "CTX"),
            arena(&desc, "DESC"),
            arena(&code, "CODE"),
            arena(&spds, "SPDS"),
            arena(&data, "DATA"),
        ],
        words,
        fbd_pointer: f.fbd_pointer,
    }
}

/// The file's text. Every item is `#[rustfmt::skip]` so that the bytes stay
/// as generated once board/mod.rs includes the file.
fn generate(b: &Built) -> String {
    let mut s = String::new();
    let w = &mut s;
    writeln!(w, "// SPDX-License-Identifier: Apache-2.0").unwrap();
    writeln!(w, "// SPDX-FileCopyrightText: 2026 Signal Slot, Inc.").unwrap();
    writeln!(w, "// GENERATED by tools/mali/panthor/tests/t6_frame_blob.rs; do not edit. Regenerate with").unwrap();
    writeln!(w, "//   YK_T6_FRAME_BLESS=1 cargo test -p yakogl-mali-panthor --test t6_frame_blob").unwrap();
    writeln!(w, "//").unwrap();
    writeln!(w, "// Z4's frame (driver/docs/nanopc-t6-mali.md, \"Submit (Z4)\"): L1's triangle frame").unwrap();
    writeln!(w, "// (tools/mali/panthor/src/l1.rs over src/mali/frame.rs) built at the Z4 VAs, in the").unwrap();
    writeln!(w, "// group's VM. Each arena's bytes are its used length; the memory behind each VA is").unwrap();
    writeln!(w, "// `*_SIZE` bytes. The stream does not start with the queue-init (`HEAP_SET`) words.").unwrap();
    writeln!(w).unwrap();
    let item = |w: &mut String, doc: &str, decl: String| {
        writeln!(w, "/// {doc}").unwrap();
        writeln!(w, "#[rustfmt::skip]").unwrap();
        writeln!(w, "{decl}").unwrap();
    };
    item(
        w,
        "Whether the frame draws the triangles (else it is the clear alone).",
        format!("pub const DRAW: bool = {DRAW};"),
    );
    item(
        w,
        "The render target (64x64 linear RGBA8, row stride 256).",
        format!("pub const TARGET_VA: u64 = {TARGET_VA:#x};"),
    );
    item(
        w,
        "The geometry buffer (`GEOMETRY_BUFFER_SIZE` bytes).",
        format!("pub const GEOMETRY_BUFFER_VA: u64 = {GEOMETRY_BUFFER_VA:#x};"),
    );
    item(
        w,
        "Its size (src/mali/frame.rs `GEOMETRY_BUFFER_BYTES`).",
        format!("pub const GEOMETRY_BUFFER_SIZE: u32 = {:#x};", l1::GEOMETRY_BUFFER_BYTES),
    );
    item(
        w,
        "The tiler heap's first chunk, as the heap descriptor names it.",
        format!("pub const HEAP_FIRST_CHUNK_VA: u64 = {HEAP_FIRST_CHUNK_VA:#x};"),
    );
    item(w, "The heap's chunk size.", format!("pub const HEAP_CHUNK_SIZE: u32 = {HEAP_CHUNK_SIZE:#x};"));
    item(w, "The registers the stream may name.", format!("pub const USER_REGS: u32 = {USER_REGS};"));
    item(
        w,
        "The tiler's max_levels the frame was built for.",
        format!("pub const TILER_MAX_LEVELS: u32 = {TILER_MAX_LEVELS};"),
    );
    item(
        w,
        "The FBD pointer RUN_FRAGMENT reads, with its tag bits.",
        format!("pub const FBD_POINTER: u64 = {:#x};", b.fbd_pointer),
    );
    for (name, va, size, bytes) in &b.arenas {
        item(w, &format!("The {} arena's VA.", name.to_lowercase()), format!("pub const {name}_VA: u64 = {va:#x};"));
        item(
            w,
            &format!("The {} arena's memory.", name.to_lowercase()),
            format!("pub const {name}_SIZE: usize = {size:#x};"),
        );
        let mut decl = format!("pub const {name}: [u8; {}] = [\n", bytes.len());
        for row in bytes.chunks(16) {
            decl.push_str("   ");
            for x in row {
                write!(decl, " 0x{x:02x},").unwrap();
            }
            decl.push('\n');
        }
        decl.push_str("];");
        item(w, &format!("The {} arena's used bytes.", name.to_lowercase()), decl);
    }
    let mut decl = format!("pub const WORDS: [u64; {}] = [\n", b.words.len());
    for row in b.words.chunks(4) {
        decl.push_str("   ");
        for x in row {
            write!(decl, " 0x{x:016x},").unwrap();
        }
        decl.push('\n');
    }
    decl.push_str("];");
    item(w, "The command stream, from its first word.", decl);
    s
}

#[test]
fn the_z4_frame_file_is_the_l1_frame_at_the_z4_vas() {
    let b = build();
    let want = generate(&b);
    if std::env::var_os("YK_T6_FRAME_BLESS").is_some() {
        std::fs::write(PATH, &want).unwrap();
    }
    let have = std::fs::read_to_string(PATH).unwrap_or_default();
    assert!(
        have == want,
        "{PATH} is not the L1 frame at the Z4 VAs: run \
         YK_T6_FRAME_BLESS=1 cargo test -p yakogl-mali-panthor --test t6_frame_blob"
    );
}

/// The file compiles as Rust and its values are the built frame's.
#[allow(dead_code)]
mod file {
    include!("../../../../driver/rust/src/board/nanopc_t6_frame.rs");
}

#[test]
fn the_file_holds_the_built_frame() {
    let b = build();
    let vas = [file::CTX_VA, file::DESC_VA, file::CODE_VA, file::SPDS_VA, file::DATA_VA];
    assert_eq!(vas, [CTX_VA, DESC_VA, CODE_VA, SPDS_VA, DATA_VA]);
    let have: [&[u8]; 5] = [&file::CTX, &file::DESC, &file::CODE, &file::SPDS, &file::DATA];
    for ((name, _, size, bytes), have) in b.arenas.iter().zip(have) {
        assert_eq!(have, &bytes[..], "{name}");
        assert!(!bytes.is_empty() && bytes.len() <= *size, "{name}: {} of {size} bytes", bytes.len());
    }
    assert_eq!(&file::WORDS[..], &b.words[..]);
    assert_eq!(file::WORDS.len(), 51, "L1's draw frame is 51 words");
    assert_eq!(file::DRAW, DRAW);
    /* RUN_FRAGMENT's FBD is in the desc arena */
    assert!((DESC_VA..DESC_VA + DESC_SIZE as u64).contains(&(file::FBD_POINTER & !63)), "{:#x}", file::FBD_POINTER);
    /* every VA the frame names is clear of Z3's firmware VAs (AS0, 0x0 to
     * 0x0410_0000), and no two of the spans overlap */
    let mut spans = [
        (CTX_VA, CTX_SIZE as u64),
        (DESC_VA, DESC_SIZE as u64),
        (CODE_VA, CODE_SIZE as u64),
        (SPDS_VA, SPDS_SIZE as u64),
        (DATA_VA, DATA_SIZE as u64),
        (GEOMETRY_BUFFER_VA, u64::from(file::GEOMETRY_BUFFER_SIZE)),
        (TARGET_VA, u64::from(l1::ROW_STRIDE * l1::HEIGHT)),
        (HEAP_FIRST_CHUNK_VA, u64::from(HEAP_CHUNK_SIZE)),
    ];
    spans.sort();
    assert!(spans[0].0 >= 0x0410_0000, "{spans:x?}");
    assert!(spans.windows(2).all(|p| p[0].0 + p[0].1 <= p[1].0), "{spans:x?}");
}
